      pt: ["Localiza-se no 53º andar e oferece uma vista deslumbrante da cidade.", "Concentra-se na arte da Ásia e da região do Pacífico.", "Permanece aberto até tarde e oferece visitas noturnas ao museu.", "Parte do complexo maior de Roppongi Hills."],
      fr: ["Situé au 53e étage, il offre une vue imprenable sur la ville.", "Se concentre sur l'art d'Asie et de la région Pacifique.", "Reste ouvert tard et propose des visites nocturnes du musée.", "Fait partie du vaste complexe de Roppongi Hills."],
