    descriptionAdvanced: {
      de: "Das Mori-Kunstmuseum ist eine der führenden Institutionen für zeitgenössische Kunst in Asien und befindet sich in der 53. Etage des Roppongi Hills Mori Tower in Tokio. Es wurde 2003 von dem Immobilienmagnaten Minoru Mori gegründet und konzentriert sich auf die Präsentation internationaler zeitgenössischer Kunst mit einem besonderen Schwerpunkt auf dem asiatisch-pazifischen Raum. Mit einer Höhe von etwa 230 Metern über dem Meeresspiegel ist es eines der höchstgelegenen Museen der Welt. Das Museum verfolgt einen offenen Ansatz und zeigt wechselnde Ausstellungen, anstatt eine permanente Sammlung in den Vordergrund zu stellen. Der Eintritt zum Museum beinhaltet oft auch den Zugang zum Tokyo City View, einer Aussichtsplattform, die einen 360-Grad-Blick auf die japanische Metropole bietet. Die Architektur des Museums wurde von Richard Gluckman entworfen und zeichnet sich durch moderne, flexible Galerieräume aus. Das Mori-Kunstmuseum ist Teil des sogenannten Art Triangle Roppongi, zu dem auch das Suntory-Kunstmuseum und das National Art Center gehören.",
      hu: "A Mori Művészeti Múzeum Ázsia egyik vezető kortárs művészeti intézménye, amely Tokióban, a Roppongi Hills Mori Tower 53. emeletén található. A 2003-ban alapított múzeumot Minoru Mori ingatlanmágnás hozta létre azzal a céllal, hogy népszerűsítse a nemzetközi kortárs művészetet, különös tekintettel az ázsiai-csendes-óceáni régióra. A tengerszint felett 230 méter magasan fekvő múzeum a világ egyik legmagasabban elhelyezkedő kiállítótere. Az intézmény nem rendelkezik állandó gyűjteménnyel, hanem folyamatosan változó időszaki kiállításokat szervez, amelyek a modern társadalmi kérdéseket és az innovatív művészeti formákat járják körül. A látogatók a belépővel gyakran a Tokyo City View kilátót is meglátogathatják, amely 360 fokos panorámát nyújt a japán fővárosra. A Richard Gluckman által tervezett galériák modern és rugalmas tereket biztosítanak a legkülönfélébb installációk számára.",
      ro: "Muzeul de Artă Mori este una dintre cele mai importante instituții de artă contemporană din Asia, fiind situat la etajul 53 al turnului Roppongi Hills Mori din Tokyo. Fondat în 2003 de către dezvoltatorul imobiliar Minoru Mori, muzeul se concentrează pe promovarea artei contemporane internaționale, cu un accent deosebit pe regiunea Asia-Pacific. Aflat la o altitudine de aproximativ 230 de metri deasupra nivelului mării, acesta este unul dintre cele mai înalte muzee din lume. Spre deosebire de alte instituții, Mori Art Museum nu expune o colecție permanentă, ci organizează expoziții temporare tematice care explorează tendințele actuale în artă și societate. Accesul în muzeu include de obicei și intrarea la platforma de observație Tokyo City View, oferind o panoramă completă asupra metropolei. Designul interior a fost realizat de arhitectul Richard Gluckman, oferind spații vaste și flexibile pentru instalații de mari dimensiuni.",
      en: "The Mori Art Museum is a leading contemporary art institution located on the 53rd floor of the Roppongi Hills Mori Tower in Tokyo. Established in 2003 by real estate developer Minoru Mori, the museum focuses on showcasing international contemporary art with a particular emphasis on the Asia-Pacific region. Situated approximately 230 meters above sea level, it is one of the highest museums in the world, offering a unique viewing experience. The museum follows an open programming philosophy, prioritizing large-scale temporary exhibitions over a permanent collection to reflect current artistic trends. Entry to the museum typically includes access to the Tokyo City View observation deck, providing 360-degree views of the sprawling Tokyo skyline. The galleries were designed by architect Richard Gluckman, featuring modern and adaptable spaces suitable for various media and installations. The museum is a key member of the Art Triangle Roppongi, a cultural cluster in the heart of the city.",
      es: "El Museo de Arte Mori muestra arte contemporáneo allí donde el propio skyline de Tokio se convierte en el fondo de la exposición. Situado en el piso 53 de la Roppongi Hills Mori Tower, combina exposiciones internacionales temporales con una vista impresionante de la ciudad. El enfoque en Asia y la región del Pacífico le otorga al museo un perfil claro que se diferencia de muchas instituciones de arte de influencia occidental. Dado que también son posibles las visitas nocturnas, el lugar funciona de día como museo de arte y de noche casi como un observatorio urbano. Plan de estudios de Plizio: Arte K8 - Arte contemporáneo en metrópolis.",
      pt: "O Museu de Arte Mori mostra arte contemporânea onde o próprio horizonte de Tóquio se torna o fundo da exposição. Localizado no 53º andar da Roppongi Hills Mori Tower, combina exposições temporárias internacionais com uma vista forte sobre a cidade. O foco na Ásia e na região do Pacífico confere ao museu um perfil claro, que se distingue de muitas instituições de arte de influência ocidental. Como também são possíveis visitas noturnas, o local funciona como um museu de arte durante o dia e quase como um observatório urbano à noite. Currículo Plizio: Artes K8 - Arte Contemporânea em Metrópoles.",
      fr: "Le musée d'art Mori présente l'art contemporain là où la skyline de Tokyo elle-même devient la toile de fond de l'exposition. Situé au 53e étage de la Roppongi Hills Mori Tower, il allie des expositions temporaires internationales à une vue imprenable sur la ville. L'accent mis sur l'Asie et la région Pacifique confère au musée un profil clair, qui se démarque de nombreuses institutions artistiques d'influence occidentale. Comme des visites nocturnes sont également possibles, le lieu fonctionne le jour comme un musée d'art et le soir presque comme un observatoire urbain. Programme Plizio : Art K8 - Art contemporain dans les métropoles.",
    },
